'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies } = require('./src/semver');

// Stale constraint from abandoned branch must be undone.
assert.deepEqual(resolve({
  a: { '2.0.0': { b: '^1.0.0', c: '^2.0.0' }, '1.0.0': { b: '^2.0.0' } },
  b: { '1.0.0': { c: '^1.0.0' }, '2.0.0': {} },
  c: { '1.0.0': {} },
}, { a: '*' }), { a: '1.0.0', b: '2.0.0' });

// Cycle, self-dep.
assert.deepEqual(resolve({ x: { '1.0.0': { y: '1.0.0', x: '1.0.0' } }, y: { '1.0.0': { x: '^1.0.0' } } }, { x: '*' }), { x: '1.0.0', y: '1.0.0' });

// Long chain.
const reg = {};
const n = 50000;
for (let i = 0; i < n; i += 1) reg['p' + i] = { '1.0.0': i + 1 < n ? { ['p' + (i + 1)]: '^1.0.0' } : {} };
assert.equal(Object.keys(resolve(reg, { p0: '*' })).length, n);

// Missing package, empty root.
assert.equal(resolve({}, { q: '*' }), null);
assert.deepEqual(resolve({}, {}), {});

// Caret rules.
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.9.0', '^1.0.0'), true);

// Eager validation of unreachable entries.
assert.throws(() => resolve({ z: { '1.0': {} } }, {}), TypeError);
console.log('ok');
